function dump(n, d) {
  if (!n) return;
  let info = { id: n.id, name: n.name, type: n.type, w: n.width, h: n.height };
  if ('fills' in n && n.fills !== figma.mixed) info.fills = n.fills;
  if ('strokes' in n && n.strokes !== figma.mixed) info.strokes = n.strokes;
  if ('cornerRadius' in n && n.cornerRadius !== figma.mixed) info.radius = n.cornerRadius;
  if ('effects' in n) info.effects = n.effects;
  if (n.type === 'TEXT') {
    info.chars = n.characters;
    info.fontName = n.fontName;
    info.fontSize = n.fontSize;
    info.lineHeight = n.lineHeight;
    info.letterSpacing = n.letterSpacing;
    if (n.fills !== figma.mixed) info.fills = n.fills;
  }
  if (n.type === 'COMPONENT' || n.type === 'INSTANCE') {
    try { info.compKey = n.key; } catch(e) {}
  }
  d.push(info);
  if (n.children && d.length < 120) for (const c of n.children) dump(c, d);
}
const out = [];
for (const id of ['1:23','1:26','1:33','1:44']) {
  const n = figma.getNodeById(id);
