const out={errors:[]};
async function link(id,dest,nav,trans){
  const n=await figma.getNodeByIdAsync(id);
  try{
    n.reactions=[{trigger:{type:'CLICK'},action:{type:'NODE',destinationId:dest,navigation:nav||'NAVIGATE',transition:trans||{type:'DISSOLVE',duration:0.25}}}];
    out[id]=n.name+' -> '+dest;
  }catch(e){ out.errors.push(id+': '+e.message); }
}
const D={type:'DISSOLVE',duration:0.25};
const UP={type:'MOVE_IN',direction:'BOTTOM',duration:0.3};
const DOWN={type:'MOVE_OUT',direction:'BOTTOM',duration:0.3};
await link('15:92','15:95','NAVIGATE',D);   // Get Started -> Home
await link('15:112','16:125','NAVIGATE',D); // balance card -> Wallet
await link('I15:137;15:72','16:125','NAVIGATE',D); // See all -> Wallet
await link('15:161','16:270','NAVIGATE',D); // FAB -> Payment
await link('16:141','15:95','NAVIGATE',D);  // back -> Home
await link('16:144','16:191','NAVIGATE',UP);// add card -> Add Card (sheet slide up)
await link('16:226','16:125','NAVIGATE',DOWN); // close -> Wallet
await link('16:265','16:125','NAVIGATE',DOWN); // Add new card -> Wallet
await link('16:298','16:303','NAVIGATE',D); // Pay now -> Receipt
await link('16:300','15:95','NAVIGATE',D);  // Cancel -> Home
await link('16:385','15:95','NAVIGATE',D);  // Home -> Home
return JSON.stringify(out);
